#[test]
fn w332_prepared_workflow_index_live_bytes() {
    use crate::{app_server::transcript::journal::source::transcript_from_scan,
        contracts::OperationOwner, domain::{ExecutionId, SessionId}};
    for n in [0, 1, 256, 4096] {
        let (session, thread, turn, exec)=(SessionId::from_u128(1), ThreadId::from_u128(2),
            TurnId::from_u128(3), ExecutionId::from_uuid(uuid::Uuid::from_u128(4)));
        let mut records=vec![record(session,Some(exec),thread,turn,1,JournalEntry::TurnOpened(TurnOpened{
            intent:None,task:AgentTask::new("fixture","/synthetic/workspace".into()),
            base_history_revision:0,module_epoch:0,config_snapshot:json!({}),
        }))];
        for i in 0..n {
            let call=ToolCall::new(format!("fixture-requested-workflow-call-{i:04}"),"fixture",json!({}));
            records.push(record(session,Some(exec),thread,turn,(i+2) as u64,
                JournalEntry::ToolCallRecorded(ToolCallRecorded{
                    call,phase:ToolCallRecordPhase::Requested{owner:OperationOwner::Workflow},
                })));
        }
        let projection=JournalProjection::build(session,records).expect("valid synthetic interrupted journal");
        let mut pass=0;
        let (rows,m,end)=crate::w332_alloc::measure(||transcript_from_scan(|visit| {
            pass+=1;
            if pass==4 {crate::w332_alloc::start_render();}
            for record in &projection.records {visit(record.clone())?;}
            if pass==3 {crate::w332_alloc::after_prepare();}
            Ok(())
        },None).unwrap());
        assert_eq!(pass,if n==0 {2}else{4});
        assert_eq!(rows.len(),n);
        for (i,row) in rows.iter().enumerate() {
            let tool=row.tool.as_ref().unwrap();
            assert_eq!(tool.call_id,format!("fixture-requested-workflow-call-{i:04}"));
            assert_eq!(tool.status,"interrupted");
        }
        let wire=serde_json::to_vec(&rows).unwrap();
        let materialized=TranscriptReplay::new(&projection.records,0).render(projection.records.iter(),None);
        assert_eq!(wire,serde_json::to_vec(&materialized).unwrap());
        if let Some(dir)=std::env::var_os("W332_WITNESS_DIR") {
            std::fs::write(std::path::PathBuf::from(dir).join(format!("{n}.json")),wire).unwrap();
        }
        eprintln!("W332 {n} {pass} {} {} {} {end}",
            m.after_prepare.unwrap_or(-1),m.start_render.unwrap_or(-1),m.peak);
    }
}
